  text-align: left;
  color: #a8b0b8;
  font-size: 13px;
  line-height: 1.8;
  letter-spacing: 1px;
}

.panel button {
  position: relative;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  letter-spacing: 3px;
  color: var(--bg-0);
  background: var(--amber);
  border: 2px solid transparent;
  padding: 13px 36px;
  cursor: pointer;
  transition:
    background 0.15s,
    transform 0.1s,
    letter-spacing 0.15s,
    box-shadow 0.15s,
    border-color 0.15s;
}

.panel button:hover {
  background: var(--amber-bright);
  border-color: #fff3c4;
  box-shadow: 0 0 20px rgba(255, 204, 85, 0.55), inset 0 0 10px rgba(255, 255, 255, 0.3);
  transform: scale(1.05);
  letter-spacing: 4px;
}

.panel button:active { transform: scale(0.98); }

#dead-screen .panel h1 {
  color: var(--hp-bad);
  text-shadow: 2px 2px 0 #000, 0 0 16px rgba(204, 51, 51, 0.55);
}

#win-screen .panel h1 {
  color: var(--hp-good);
  text-shadow: 2px 2px 0 #000, 0 0 16px rgba(85, 204, 85, 0.55);
}
